package co.kr.badara.dolswevoice;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private final int GREEN=Color.rgb(40,83,69),MUTED=Color.rgb(116,131,122),BG=Color.rgb(246,247,242);private LinearLayout root,body,tabs;private TextView live;private Config cfg;private String page="home",pendingMode="wake";private final ExecutorService io=Executors.newSingleThreadExecutor();private final Map<String,EditText> aliasFields=new LinkedHashMap<>();private boolean busy=false;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(live!=null)live.setText(i.getStringExtra("text"));}};
 public void onCreate(Bundle b){super.onCreate(b);cfg=new Config(this);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);show("home");}
 protected void onStart(){super.onStart();if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,new IntentFilter(VoiceService.EVENT),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,new IntentFilter(VoiceService.EVENT));}protected void onStop(){super.onStop();unregisterReceiver(receiver);}protected void onDestroy(){io.shutdown();super.onDestroy();}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);v.setPadding(0,dp(6),0,dp(6));return v;}
 private Button button(String s,Runnable action,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(primary?Color.WHITE:GREEN);b.setBackground(shape(primary?GREEN:Color.WHITE,12));b.setPadding(dp(12),dp(8),dp(12),dp(8));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.setMargins(0,dp(8),0,dp(4));b.setLayoutParams(lp);b.setOnClickListener(v->action.run());return b;}
 private EditText field(LinearLayout parent,String label,String value,String hint,boolean secret){parent.addView(text(label,12,MUTED,false));EditText e=new EditText(this);e.setSingleLine(!label.equals("호출어"));e.setText(value);e.setHint(hint);e.setTextSize(15);e.setTextColor(GREEN);e.setPadding(dp(12),dp(12),dp(12),dp(12));e.setBackground(shape(Color.WHITE,10));if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);parent.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(18),dp(14),dp(18),dp(14));c.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(10));body.addView(c,lp);return c;}
 private void show(String p){page=p;live=null;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(20),dp(12),dp(20),dp(12));root.setFitsSystemWindows(true);setContentView(root);root.addView(text("DOLSWE  /  HOME ASSISTANT",10,MUTED,true));root.addView(text("돌쇠 음성비서",26,GREEN,true));tabs=new LinearLayout(this);for(String[] t:new String[][]{{"home","음성"},{"devices","장치 별칭"},{"settings","설정"}}){Button b=button(t[1],()->show(t[0]),p.equals(t[0]));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(42),1);lp.setMargins(dp(3),dp(6),dp(3),dp(10));tabs.addView(b,lp);}root.addView(tabs);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(6),0,dp(24));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(p.equals("settings"))settings();else if(p.equals("devices"))devices();else home();}
 private void home(){LinearLayout c=card();c.addView(text("말로 부르는 우리 집",20,GREEN,true));c.addView(text(cfg.wakes(),24,GREEN,true));live=text(VoiceService.running?VoiceService.status:cfg.last(),15,MUTED,false);c.addView(live);c.addView(text("음성은 휴대폰에서 처리합니다. 지정한 레이블과 별칭의 장치만 연결됩니다.",12,MUTED,false));body.addView(button("호출 대기 시작",()->start("wake"),true));body.addView(button("마이크로 명령",()->start("command"),false));body.addView(button("호출어 인식 테스트",()->start("test"),false));body.addView(button("대기 중지",()->{stopService(new Intent(this,VoiceService.class));if(live!=null)live.setText("대기 중지");},false));LinearLayout guide=card();guide.addView(text(cfg.dry()?"현재 시험 모드 · 실제 장치 조작 안 함":"현재 실제 제어 모드",14,GREEN,true));guide.addView(text("① 설정에 HA 주소·토큰·레이블 입력\n② 장치 별칭에서 목록 불러오기\n③ 이름을 연결하고 저장\n④ 호출 대기 시작\n\n예: ‘돌쇠야, 거실 불 켜줘’\n‘이모님’ → 응답 후 ‘안방 선풍기 꺼줘’",13,MUTED,false));guide.addView(text("SenseVoice INT8 (한국어 검증판) · 한국어 / Silero VAD\n화면이 꺼져도 동작하도록 알림과 마이크 권한을 허용하세요. 강제 종료·재부팅 후에는 앱에서 다시 시작합니다.",12,MUTED,false));}
 private void settings(){EditText base=field(body,"HA 주소",cfg.base(),"https://ha.example.com",false);EditText label=field(body,"HA 엔티티에 지정한 레이블 이름",cfg.label(),"엔티티의 레이블 이름과 똑같이 입력",false);EditText token=field(body,"HA 장기 액세스 토큰","","처음 연결할 때 입력 / 빈 칸이면 기존 토큰 유지",true);body.addView(text("토큰은 HA 프로필 → 보안 → 장기 액세스 토큰에서 직접 만들 수 있습니다. 이 앱은 토큰을 휴대폰 보안 저장소로 암호화해 저장합니다.",12,MUTED,false));EditText wakes=field(body,"호출어",cfg.wakes(),"돌쇠야, 이모님",false);body.addView(text("쉼표로 나눠 여러 개를 입력하세요. 문장 앞에서 호출어가 일치할 때 반응합니다. ‘호출어 인식 테스트’에서 실제 인식 결과를 확인하세요.",12,MUTED,false));Switch near=new Switch(this);near.setText("호출어 발음 보정 (오반응 시 끄기)");near.setChecked(cfg.p.getBoolean("nearWake",true));near.setPadding(0,dp(12),0,dp(12));body.addView(near);Switch dry=new Switch(this);dry.setText("시험 모드 (실제 장치 조작 안 함)");dry.setChecked(cfg.dry());dry.setPadding(0,dp(12),0,dp(12));body.addView(dry);body.addView(button("연결 설정 저장",()->{try{cfg.save(base.getText().toString(),label.getText().toString(),wakes.getText().toString(),token.getText().toString(),dry.isChecked());cfg.p.edit().putBoolean("nearWake",near.isChecked()).apply();stopService(new Intent(this,VoiceService.class));token.setText("");message("저장했습니다. 장치 목록을 불러오고 호출 대기를 다시 시작하세요.");}catch(Exception e){message(VoiceService.message(e));}},true));body.addView(button("배터리 제한 설정 열기",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))),false));body.addView(text("휴대폰 설정에서 배터리 사용을 ‘제한 없음’으로 선택하세요. 알림을 끄거나 앱을 강제 종료하면 호출 대기가 중단될 수 있습니다. 호출 대기는 일반 앱보다 배터리를 더 사용합니다.\n\n버전 1.0.2",12,MUTED,false));}
 private void devices(){body.addView(text("연동 레이블: "+(cfg.label().isEmpty()?"설정에서 먼저 입력":cfg.label()),15,GREEN,true));body.addView(text("해당 레이블이 붙은 엔티티 또는 장치의 항목만 표시합니다. 별칭은 HA의 이름을 바꾸지 않습니다.",12,MUTED,false));body.addView(button(busy?"불러오는 중…":"HA 장치 목록 불러오기",this::sync,false));aliasFields.clear();JSONArray cache=cfg.cache();for(int i=0;i<cache.length();i++){JSONObject o=cache.optJSONObject(i);if(o==null)continue;LinearLayout c=card();String id=o.optString("id");c.addView(text(o.optString("name"),16,GREEN,true));c.addView(text(id+" · "+o.optString("state"),11,MUTED,false));EditText alias=field(c,"앱에서 부를 이름",cfg.alias(id),"예: 거실 불",false);aliasFields.put(id,alias);}if(cache.length()==0)body.addView(text("목록이 비어 있으면 HA 레이블의 철자와 장치·엔티티에 레이블이 붙었는지 확인하세요.",13,MUTED,false));else body.addView(button("장치 별칭 저장",()->{try{JSONObject a=new JSONObject();for(Map.Entry<String,EditText> e:aliasFields.entrySet())a.put(e.getKey(),e.getValue().getText().toString().trim());cfg.saveAliases(a);message("별칭을 저장했습니다.");}catch(Exception e){message(VoiceService.message(e));}},true));}
 private void sync(){if(busy)return;busy=true;message("HA 레이블을 확인하고 있습니다…");io.execute(()->{try{List<HaClient.Entity> entities=cfg.client().list(cfg.label());cfg.cache(entities);runOnUiThread(()->{busy=false;show("devices");message(entities.size()+"개 항목을 불러왔습니다.");});}catch(Exception e){runOnUiThread(()->{busy=false;message(VoiceService.message(e));});}});}
 private void start(String mode){pendingMode=mode;try{if(!mode.equals("test")){if(cfg.token().isEmpty()||cfg.label().isEmpty())throw new Exception("설정에서 HA 연결과 레이블을 먼저 저장해주세요.");if(cfg.targets().isEmpty())throw new Exception("장치 별칭을 하나 이상 저장해주세요.");}List<String> permissions=new ArrayList<>();if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)permissions.add(android.Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permissions.add(android.Manifest.permission.POST_NOTIFICATIONS);if(!permissions.isEmpty()){requestPermissions(permissions.toArray(new String[0]),7);return;}startForegroundService(new Intent(this,VoiceService.class).putExtra("mode",mode));if(live!=null)live.setText("음성 모델 준비 중…");}catch(Exception e){message(VoiceService.message(e));}}
 public void onRequestPermissionsResult(int request,String[] p,int[] g){super.onRequestPermissionsResult(request,p,g);if(request==7&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){try{startForegroundService(new Intent(this,VoiceService.class).putExtra("mode",pendingMode));if(live!=null)live.setText("음성 모델 준비 중…");}catch(Exception e){message(VoiceService.message(e));}}else message("마이크 권한이 있어야 음성인식을 사용할 수 있습니다.");}
 private void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("확인",null).show();}
}
